import type { AstDetectiveDifficulty as D, AstDetectiveQuestion as Q, AstDetectiveQuestionType as K, AstDetectiveTopic as T } from "./types";

export const AST_DETECTIVE_BANK_VERSION = "1.0-draft";

type Spec = [string,T,D,K,string,string,string[],number,string,string,string[]];
const q = ([id,topic,difficulty,type,title,stem,answers,correct,explanation,teachingPoint,sourceIds]: Spec): Q => ({
  id, title, topic, difficulty, type, learningObjective: `Explain ${title.toLowerCase()} in an AST reasoning workflow.`, stem,
  choices: answers.map((text,index)=>({id:String.fromCharCode(97+index),text})), correctChoiceIds:[String.fromCharCode(97+correct)],
  explanation, incorrectExplanations:Object.fromEntries(answers.map((text,index)=>[String.fromCharCode(97+index),index===correct?"This is the best-supported interpretation.":`“${text}” overstates, misattributes, or bypasses the evidence in this case.`])),
  teachingPoint, sourceIds, reviewStatus:"Draft"
});

